import { z } from "zod"

// Import generated schemas for simulation types
import SimulationNodeSchema from './SimulationNode.v1.zod';
import SimulationParametersSchema from './SimulationParameters.v1.zod';
import SimulationResultSchema from './SimulationResult.v1.zod';

// Base schema from JSON Schema (generated by json-schema-to-zod)
// Note: The generated schema has inline definitions, but we use separate schemas
const BaseScenarioSchema = z.object({ 
  "id": z.number().int().describe("Unique scenario identifier").optional(), 
  "name": z.string().describe("Scenario name"), 
  "description": z.union([z.string().describe("Scenario description"), z.null().describe("Scenario description")]).describe("Scenario description").optional(), 
  "modelId": z.number().int().describe("ID of the model this scenario belongs to"), 
  "nodes": z.array(SimulationNodeSchema).describe("Array of simulation nodes (snapshot at scenario creation)").optional().default([]), 
  "initialValues": z.record(z.number()).describe("Initial node values for this scenario").optional().default({}), 
  "clampedNodes": z.array(z.string()).describe("Node IDs that should remain clamped during simulation").optional().default([]), 
  "simulationParams": SimulationParametersSchema.optional(), 
  "results": SimulationResultSchema.optional(), 
  "createdAt": z.string().datetime({ offset: true }).describe("Timestamp when scenario was created").optional(), 
  "updatedAt": z.union([z.string().datetime({ offset: true }).describe("Timestamp when scenario was last updated"), z.null().describe("Timestamp when scenario was last updated")]).describe("Timestamp when scenario was last updated").optional() 
}).describe("A simulation scenario with modified node values and simulation parameters");

// Enhanced schemas with proper date handling for API
export const ScenarioSchema = BaseScenarioSchema.extend({
  createdAt: z.string().or(z.date()).optional(),
  updatedAt: z.string().or(z.date()).nullable().optional(),
  nodes: z.array(SimulationNodeSchema).optional(),
  initialValues: z.record(z.string(), z.number()).optional(),
  clampedNodes: z.array(z.string()).optional(),
});

export const ScenarioStorageSchema = z.object({
  id: z.number(),
  modelId: z.number(),
  name: z.string(),
  description: z.string().nullable(),
  nodes: z.array(SimulationNodeSchema),
  initialValues: z.record(z.string(), z.number()),
  clampedNodes: z.array(z.string()).default([]),
  simulationParams: SimulationParametersSchema.nullable(),
  results: SimulationResultSchema.nullable(),
  createdAt: z.date(),
  updatedAt: z.date().nullable()
});

export const CreateScenarioSchema = ScenarioSchema.omit({ id: true, createdAt: true, updatedAt: true });

export type Scenario = z.infer<typeof ScenarioSchema>;
export type ScenarioStorage = z.infer<typeof ScenarioStorageSchema>;

// Keep default export for codegen compatibility (will be overwritten on next codegen)
export default BaseScenarioSchema;
